import unreal
for node in unreal.ObjectIterator(unreal.EdGraphNode):
    if node.get_class().get_name() != 'NiagaraNodeFunctionCall': continue
    p=node.get_path_name()
    if 'NS_SSPR_ProjTest' not in p: continue
    vals=[]
    for key in ('function_script','function_name','signature'):
        try:
            v=node.get_editor_property(key)
            vals.append((key,v.get_path_name() if hasattr(v,'get_path_name') and v else str(v)))
        except Exception as exc: vals.append((key,'ERR:' + str(exc)))
    print('CALL=' + p + '|VALS=' + repr(vals))
